update pages set contenu = '{"sections":[]}'::jsonb where path = '/implantations/paris/';
update pages set contenu = jsonb_set(contenu, '{sections}', (contenu->'sections') || '[{"type":"heros","h1":"Maintenir vos machines dans le tissu le plus dense de France","mecanisme":"En Île-de-France, la contrainte n''est pas la machine, c''est ce qui l''entoure : un atelier en fond de cour sans aire de déchargement, un entrepôt de couronne qui ne peut pas s''arrêter avant 22h, des riverains à trois mètres du portail. Nos techniciens basés à Paris préparent l''accès avant de partir sur site.","cta":"Faire chiffrer ma maintenance en Île-de-France","telephone":"04 78 33 72 05","phraseDelai":"Nous vous rappelons dans l''heure, du lundi au vendredi de 8h00 à 18h30. Astreinte 24/24 et 7/7 en option, nuits, week-ends et jours fériés."},{"type":"chiffres","chiffres":[{"valeur":"+ 120","libelle":"clients industriels accompagnés, dont plus de 80 réguliers"},{"valeur":"10 %","libelle":"des candidats retenus, entretien technique et comportemental, résultats partagés"},{"valeur":"10","libelle":"hubs de techniciens en France, dont un à Paris, plus notre siège lyonnais et nos agences de Montréal, Dubaï et Madrid"}]},{"type":"probleme","punchline":"Le technicien est disponible, la pièce est en stock, et il met la matinée à se garer. En Île-de-France, la moitié du coût d''une intervention se joue avant qu''elle commence.","puces":[{"accroche":"L''accès se négocie rue par rue.","texte":"Zone à circulation restreinte, cour étroite, monte-charge saturé : sans préparation, le déplacement est perdu."},{"accroche":"Les fenêtres d''arrêt sont courtes.","texte":"Logistique de couronne en flux tendu, ateliers de nuit, dépôts de transport : les opérations lourdes se calent entre deux rotations."},{"accroche":"Les riverains sont à portée de bruit.","texte":"Meulage, levage, essais moteur : ce qui passe en zone industrielle isolée se négocie ici avec le voisinage."},{"accroche":"La pénurie de techniciens est maximale.","texte":"Le bassin francilien absorbe plus de profils de maintenance que ses formations n''en produisent, et beaucoup basculent vers le tertiaire."},{"accroche":"Le prestataire de passage ne revient jamais deux fois.","texte":"Personne différente à chaque visite, aucun historique, et la même panne qui repart pour un tour."}]}]'::jsonb) where path = '/implantations/paris/';
update pages set contenu = jsonb_set(contenu, '{sections}', (contenu->'sections') || '[{"type":"offre","lignes":[{"prestation":{"accroche":"La préparation d''accès avant le départ","texte":"créneaux, aire de déchargement, monte-charge, badges, plan de prévention."},"benefice":"Le technicien entre et travaille, au lieu de chercher son chemin pendant une demi-journée."},{"prestation":{"accroche":"Des interventions calées sur vos fenêtres réelles","texte":", tôt le matin, entre deux équipes, de nuit."},"benefice":"Une opération lourde ne mange jamais une vague de préparation ni une rotation de quai."},{"prestation":{"accroche":"Le champ technique complet","texte":"[mécanique](/expertises/mecanique/), [électricité](/expertises/electrique/), [électromécanique](/expertises/electromecanique/), [automatisme](/expertises/automatisme/), [hydraulique](/expertises/hydraulique/), [pneumatique](/expertises/pneumatique/), [robotique](/expertises/robotique/)."},"benefice":"Un parc francilien mélange toujours plusieurs technologies : un seul contrat les couvre."},{"prestation":{"accroche":"Le respect des process réglementés","texte":"salles propres, traçabilité, qualification des équipements."},"benefice":"Pharmacie, cosmétique et agroalimentaire gardent une documentation conforme à chaque passage."},{"prestation":{"accroche":"Astreinte 24/24 et 7/7 en option","texte":"pour les sites en continu et les utilités critiques."},"benefice":"Une panne d''eau de process ou d''air comprimé un dimanche trouve un technicien."},{"prestation":{"accroche":"Un hub de techniciens à Paris","texte":", l''un de nos 10 hubs en France, adossé au siège lyonnais."},"benefice":"Les techniciens qui interviennent chez vous sont basés dans le bassin, pas dépêchés depuis l''autre bout du pays."},{"prestation":{"accroche":"Relais du bassin","texte":"[Essonne](/implantations/paris/essonne/) au sud, [Rouen](/implantations/paris/rouen/) sur l''axe Seine aval."},"benefice":"Un groupe réparti entre petite couronne et vallée de la Seine garde un seul interlocuteur."}]},{"type":"deroule","etapes":[{"titre":"L''appel qualifié","texte":"Vous exposez la panne au 04 78 33 72 05, et nous rappelons dans l''heure aux horaires ouvrés. Symptômes, historique, criticité : le diagnostic commence au téléphone."},{"titre":"La logistique d''accès","texte":"Adresse exacte, horaires du site, contraintes de circulation, moyens de levage disponibles, habilitations attendues. Ce point évite le déplacement inutile."},{"titre":"La préparation technique","texte":"Profil choisi selon la technologie, pièces pressenties, outillage embarqué. Un atelier sans pont roulant change la méthode."},{"titre":"L''intervention","texte":"Accueil sécurité, consignation, diagnostic, réparation, essais."},{"titre":"Le redémarrage tracé","texte":"Essais réalisés, mise en service, seuils d''alerte relevés avec vos opérateurs."},{"titre":"Le compte rendu","texte":"Causes, actions, pièces, préconisations, versés dans votre GMAO. Vos données restent chez vous."}]},{"type":"garanties","puces":[{"accroche":"Un interlocuteur stable, pas un numéro","texte":"un chargé d''affaires nommé qui connaît votre site, ses accès et son historique, et le même technicien aussi longtemps que possible."},{"accroche":"Une compétence vérifiée avant l''arrivée","texte":"entretien technique et comportemental, 10 % des candidats retenus, résultats d''évaluation présentés avant la première visite."},{"accroche":"La confidentialité des données de procédé","texte":"les relevés et les historiques de vos équipements restent chez vous, lisibles par votre direction, jamais réutilisés ailleurs."}]}]'::jsonb) where path = '/implantations/paris/';
update pages set contenu = jsonb_set(contenu, '{sections}', (contenu->'sections') || '[{"type":"cta","question":"Besoin d''un mainteneur qui règle la question de l''accès avant celle de la panne ?","bouton":"Faire chiffrer ma maintenance en Île-de-France","rappel":"Ou appelez le 04 78 33 72 05, du lundi au vendredi de 8h00 à 18h30. Rappel dans l''heure."},{"type":"preuves","preuves":[{"titre":"Un technicien de maintenance expérimenté affecté en continu sur un site proche de Paris","texte":"lignes de production en forte activité, 2025 et 2026","lienLibelle":"Étude de cas FDJ : site proche de Paris","lienHref":"/preuves/fdj/"},{"titre":"Construction d''un site industriel de R&D près de Paris","texte":"pilotage de chantier, coordination et jalons, par Orthus, filiale Migen","lienLibelle":"Étude de cas ORTHUS x ECOCEM : nouveau site","lienHref":"/preuves/orthus-ecocem/"},{"titre":"Un technicien intégré pendant l''arrêt estival pour tenir les équipements critiques","texte":"réseau national piloté depuis Paris, été 2025","lienLibelle":"Étude de cas OGF : arrêt estival","lienHref":"/preuves/ogf-arret-estival/"},{"titre":"Un électromécanicien habilité risque chimique mobilisé 6 mois","texte":"remise en état d''un site de traitement des eaux industrielles","lienLibelle":"Étude de cas SUEZ : remise en état d''un site","lienHref":"/preuves/suez-remise-en-etat/"},{"titre":"10 à 20 techniciens une semaine sur deux, par créneaux de 8 heures","texte":"centre logistique ORY4, depuis septembre 2022, contrat annuel","lienLibelle":"Étude de cas AMAZON : maintien d''un centre logistique","lienHref":"/preuves/amazon-centre-logistique/"}]}]'::jsonb) where path = '/implantations/paris/';
update pages set contenu = jsonb_set(contenu, '{sections}', (contenu->'sections') || '[{"type":"objections","questions":[{"question":"Notre atelier est en fond de cour, sans quai ni pont roulant. Vous intervenez quand même ?","reponse":"Oui, à condition de le savoir avant. La qualification téléphonique couvre l''accès, les moyens de levage disponibles et les créneaux de circulation. Le technicien part avec l''outillage adapté et, si besoin, les moyens de manutention. C''est le quotidien francilien, pas une exception."},{"question":"Intervenez-vous vraiment sur place, à Paris ?","reponse":"Oui. Paris est l''un de nos 10 hubs de techniciens en France : les professionnels qui franchissent votre portail sont basés dans le bassin. Derrière eux, notre siège lyonnais et nos agences de Montréal, Dubaï et Madrid. Ce qui compte sur votre site reste le niveau du technicien, son outillage et ses habilitations."},{"question":"Quels sont vos délais d''intervention à Paris ?","reponse":"Nous ne vendons pas un chiffre. L''engagement tenu est le rappel dans l''heure aux horaires ouvrés, une qualification qui évite les allers-retours, et l''astreinte 24/24 et 7/7 en option pour les nuits et les week-ends. Sur une panne critique, le bon technicien du premier coup rend plus de temps qu''une promesse."},{"question":"Intervenez-vous en dehors des horaires d''exploitation ?","reponse":"Oui. Les opérations lourdes se planifient tôt le matin, entre deux équipes ou de nuit, selon vos rotations. Pour les dépôts de transport et les plateformes, c''est la règle plutôt que l''exception : les modalités et le circuit d''appel sont écrits au contrat."},{"question":"Combien coûte un contrat de maintenance ?","reponse":"Zéro arrêt part de sur devis, trois niveaux de couverture, engagement type de 6 mois renouvelable. Un parc francilien compact avec une astreinte large ne se chiffre pas comme un site étendu visité deux fois par an. Le diagnostic de départ n''est pas facturé, et le périmètre figure au contrat."},{"question":"Travaillez-vous avec les PME comme avec les grands groupes ?","reponse":"Oui. Un atelier de vingt salariés attend la même rigueur qu''un site d''un grand groupe, et l''arrêt lui coûte proportionnellement plus cher. Les formats vont de l''intervention unique au [technicien en résidence](/offres/residence/), avec une prise de poste en 2 à 3 semaines et le remplacement assuré."},{"question":"Suivez-vous les process réglementés, salles propres et traçabilité ?","reponse":"Oui. Pharmacie, cosmétique et agroalimentaire imposent une qualité documentaire au moins égale au geste technique : comptes rendus complets, historique par équipement, pièces tracées. Nos techniciens travaillent dans vos procédures, pas à côté."}]},{"type":"ctaFinal","question":"Besoin de fiabiliser un parc francilien sans bloquer l''exploitation ?","bouton":"Faire chiffrer ma maintenance en Île-de-France","rappel":"ou appelez le 04 78 33 72 05, rappel dans l''heure aux horaires ouvrés."}]'::jsonb) where path = '/implantations/paris/';
